// cat.entity.ts
import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  OneToOne,
  OneToMany,
  ManyToMany,
  JoinColumn,
  JoinTable,
} from 'typeorm';
import { Passport } from './passport.entity';
import { Toy } from './toy.entity';
import { Owner } from './owner.entity';

@Entity()
export class Cat {
  @PrimaryGeneratedColumn()
  id: number;

  @Column()
  name: string;

  // 1-1: eager loading is declared on the ENTITY, not per query.
  @OneToOne(() => Passport, { eager: true })
  @JoinColumn()
  passport: Passport;

  // 1-N: a collection relation, also entity-level eager.
  @OneToMany(() => Toy, (toy) => toy.cat, { eager: true })
  toys: Toy[];

  // N-N: resolved through a join table, also entity-level eager.
  @ManyToMany(() => Owner, (owner) => owner.cats, { eager: true })
  @JoinTable()
  owners: Owner[];
}

// cats.service.ts
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Cat } from './cat.entity';

@Injectable()
export class CatsService {
  constructor(
    @InjectRepository(Cat)
    private readonly catRepository: Repository<Cat>,
  ) {}

  // List query: no relations option, no where, no take/skip.
  // Because Cat has eager: true on passport/toys/owners, this STILL
  // hydrates all three relations for every row via a wide multi-join,
  // multiplying rows per parent, and returns the full unbounded result set.
  async findAll(): Promise<Cat[]> {
    return this.catRepository.find();
  }

  // Detail query: legitimately needs the fully hydrated cat graph.
  async findOne(id: number): Promise<Cat | null> {
    return this.catRepository.findOne({ where: { id } });
  }
}

// cats.controller.ts
import { Controller, Get, Param, ParseIntPipe } from '@nestjs/common';
import { CatsService } from './cats.service';
import { Cat } from './cat.entity';

@Controller('cats')
export class CatsController {
  constructor(private readonly catsService: CatsService) {}

  // Feeds a list view that only renders id + name.
  @Get()
  async findAll(): Promise<Cat[]> {
    return this.catsService.findAll();
  }

  // Feeds a detail view that renders the full graph (passport/toys/owners).
  @Get(':id')
  async findOne(@Param('id', ParseIntPipe) id: number): Promise<Cat | null> {
    return this.catsService.findOne(id);
  }
}
